package dev.voyage.workbench;
import android.content.*;import android.database.*;import android.database.sqlite.*;import org.json.*;import java.util.*;
final class Store extends SQLiteOpenHelper {
 final Core core;
 Store(Context context)throws Exception{super(context,"workbench.db",null,1);core=new Core(context);setWriteAheadLoggingEnabled(true);}
 public void onConfigure(SQLiteDatabase d){d.execSQL("PRAGMA synchronous=FULL");try(Cursor c=d.rawQuery("PRAGMA busy_timeout=10000",null)){c.moveToFirst();}}
 public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE projects(id TEXT PRIMARY KEY,name TEXT,updated INTEGER,revision INTEGER,body TEXT)");d.execSQL("CREATE TABLE checkpoints(id TEXT PRIMARY KEY,project_id TEXT,label TEXT,created INTEGER,source TEXT)");d.execSQL("CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT)");}
 public void onUpgrade(SQLiteDatabase d,int old,int n){}
 JSONArray rows(String sql,String...args)throws Exception{try(Cursor c=getReadableDatabase().rawQuery(sql,args)){if(c instanceof SQLiteCursor)((SQLiteCursor)c).setWindow(new CursorWindow("voyage",64L*1024*1024));JSONArray a=new JSONArray();while(c.moveToNext()){JSONObject r=new JSONObject();for(int i=0;i<c.getColumnCount();i++)r.put(c.getColumnName(i),c.getType(i)==Cursor.FIELD_TYPE_INTEGER?c.getLong(i):c.getString(i));a.put(r);}return a;}}
 JSONArray list()throws Exception{JSONArray rows=rows("SELECT id,name,updated,revision FROM projects ORDER BY updated DESC");for(int j=0;j<rows.length();j++){JSONObject row=rows.getJSONObject(j);JSONObject summary=(JSONObject)core.call(new JSONObject().put("operation","projectSummary").put("args",new JSONArray().put(project(row.getString("id")))));for(Iterator<String> keys=summary.keys();keys.hasNext();){String key=keys.next();row.put(key,summary.get(key));}}return rows;}
 JSONObject get(String id,long known)throws Exception{JSONArray a=rows("SELECT revision,body FROM projects WHERE id=?",id);if(a.length()==0)throw new Exception("Project not found");JSONObject r=a.getJSONObject(0);if(r.getLong("revision")==known)return new JSONObject().put("unchanged",true).put("revision",known);return new JSONObject().put("revision",r.getLong("revision")).put("project",new JSONObject(r.getString("body")));}
 JSONObject project(String id)throws Exception{return get(id,-1).getJSONObject("project");}
 JSONObject create(String name,String source)throws Exception{String id=UUID.randomUUID().toString();JSONObject p=(JSONObject)core.call(new JSONObject().put("operation","create").put("id",id).put("name",name).put("source",source).put("now",System.currentTimeMillis()));getWritableDatabase().execSQL("INSERT INTO projects VALUES(?,?,?,?,?)",new Object[]{id,name,System.currentTimeMillis(),1,p.toString()});return get(id,-1);}
 synchronized JSONObject dispatch(String id,JSONObject command)throws Exception{SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{JSONObject p=project(id);String beforeCheckpointId=UUID.randomUUID().toString(),afterCheckpointId=UUID.randomUUID().toString();command.put("now",System.currentTimeMillis()).put("beforeCheckpointId",beforeCheckpointId).put("afterCheckpointId",afterCheckpointId);JSONObject next=(JSONObject)core.call(new JSONObject().put("operation","reduce").put("project",p).put("command",command));if(!p.getString("activeSource").equals(next.getString("activeSource"))){checkpointWithId(id,"taskDone".equals(command.getString("type"))?"Before automatic assistant apply":"Before "+command.getString("type"),p.getString("activeSource"),beforeCheckpointId);JSONArray receipts=next.optJSONArray("noteChanges"),previous=p.optJSONArray("noteChanges");if(receipts!=null&&receipts.length()>(previous==null?0:previous.length()))checkpointWithId(id,"After note-linked work: "+receipts.getJSONObject(receipts.length()-1).getString("title"),next.getString("activeSource"),afterCheckpointId);}d.execSQL("UPDATE projects SET name=?,updated=?,revision=revision+1,body=? WHERE id=?",new Object[]{next.getString("name"),next.getLong("updated"),next.toString(),id});d.setTransactionSuccessful();}finally{d.endTransaction();}return get(id,-1);}
 void checkpoint(String id,String label,String source)throws Exception{checkpointWithId(id,label,source,UUID.randomUUID().toString());}
 void checkpointWithId(String id,String label,String source,String checkpointId)throws Exception{getWritableDatabase().execSQL("INSERT INTO checkpoints VALUES(?,?,?,?,?)",new Object[]{checkpointId,id,label,System.currentTimeMillis(),source==null?project(id).getString("activeSource"):source});}
 JSONArray history(String id)throws Exception{return rows("SELECT id,label,created,length(source) AS size FROM checkpoints WHERE project_id=? ORDER BY created DESC",id);}
 JSONObject restore(String id,String checkpoint)throws Exception{JSONObject row=rows("SELECT source,label FROM checkpoints WHERE id=? AND project_id=?",checkpoint,id).getJSONObject(0);return dispatch(id,new JSONObject().put("type","stage").put("id",UUID.randomUUID().toString()).put("source",row.getString("source")).put("title","Restore: "+row.getString("label")).put("kind","checkpoint"));}
 String setting(String key)throws Exception{JSONArray r=rows("SELECT value FROM settings WHERE key=?",key);return r.length()==0?"":r.getJSONObject(0).getString("value");}
 void setting(String key,String value){getWritableDatabase().execSQL("INSERT OR REPLACE INTO settings VALUES(?,?)",new Object[]{key,value});}
 void recover()throws Exception{JSONArray a=list();for(int i=0;i<a.length();i++){String id=a.getJSONObject(i).getString("id");JSONArray tasks=project(id).getJSONArray("tasks");boolean active=false;for(int j=0;j<tasks.length();j++)if(Arrays.asList("PREPARED","RUNNING").contains(tasks.getJSONObject(j).getString("state")))active=true;if(active)dispatch(id,new JSONObject().put("type","recover"));}}
}
